<h1>Checkout</h1><?php if(!empty($_SESSION['flash'])): ?><p class="notice"><?= e($_SESSION['flash']); unset($_SESSION['flash']); ?></p><?php endif; ?><?php if(!$items): ?><p>Your cart is empty.</p><?php else: ?><table><tr><th>Item</th><th>Total</th></tr><?php foreach($items as $item): ?><tr><td><?= e($item['product']['name']) ?></td><td>₹<?= e((string)$item['line_total']) ?></td></tr><?php endforeach; ?></table><h2>Total: ₹<?= e((string)$total) ?></h2><?php if(!empty($secrets['razorpay_key_id'])): ?><button id="pay-now">Pay with Razorpay</button><script src="https://checkout.razorpay.com/v1/checkout.js"></script><script>document.getElementById('pay-now').onclick=async()=>{const r=await fetch('/checkout/create-order',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'amount=<?= $total*100 ?>'});const order=await r.json();new Razorpay({key:'<?= e($secrets['razorpay_key_id']) ?>',amount:order.amount,currency:'INR',order_id:order.id,name:'Sri Panchami Spiritual',handler:async(resp)=>{const body=new URLSearchParams({order_id:order.id,payment_id:resp.razorpay_payment_id,signature:resp.razorpay_signature});const vr=await fetch('/payment/verify',{method:'POST',body});alert((await vr.json()).verified?'Payment verified':'Payment verification failed');}}).open();};</script><?php else: ?><p class="notice">Razorpay is not configured yet.</p><?php endif; ?><?php endif; ?>
